using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Drawing;
using System.Windows.Forms;
using MedGas2024.Core;
using MedGas2024.UI;
public static class FamilyTests
{
    static List<string> log=new List<string>();static string evidence;static void Check(bool ok,string text){if(!ok)throw new Exception(text);log.Add("PASS: "+text);Console.WriteLine(log.Last());}
    static IEnumerable<Control> All(Control p){foreach(Control c in p.Controls){yield return c;foreach(var d in All(c))yield return d;}}
    static T Find<T>(Control p,string name)where T:Control{return All(p).OfType<T>().Single(c=>c.Name==name);}
    static bool Reject(Action a){try{a();return false;}catch(ArgumentException){return true;}}
    static void Capture(Form f,string name){Application.DoEvents();using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(evidence,name+".png"));}}
    [STAThread]public static int Main(string[] args){evidence=Path.Combine(args[0],"evidence");Application.EnableVisualStyles();try{
        var source=new FamilySource{Handle="A1",Fingerprint="source-state",Layer="Mr.T_CO2_D15_RAW",Type="R0-source",Text="D15.CO2",Label="CO2",Prefix="Mr.T",Code="CO2",Suffix="RAW",Color="RGB 12,130,210",Font="Bahnschrift • Bold=True",Height=2.5,Dash=40,Padding=.6,Scale=.15,Width=15,WidthNote="15",Direction="Giữ cờ U/R native"};var request=new FamilyRequest{Code="CO2",Suffix="RAW",Diameters="D35, 28; DN35 15"};var rows=request.Rows(source);Check(rows.Select(r=>r.Diameter).SequenceEqual(new[]{15,28,35})&&rows[1].Text=="D28.CO2"&&rows[1].Name=="Mr.T_CO2_D28_RAW","New diameters are parsed, deduplicated and named within the source family");Check(Reject(()=>new FamilyRequest{Code="CO2",Diameters="28,nope"}.Rows(source))&&Reject(()=>new FamilyRequest{Code="bad/name",Diameters="28"}.Rows(source)),"Invalid dimensions and target names are rejected before inspection");
        int scans=0,writes=0;using(var f=new FamilySizesForm(source,r=>{scans++;var p=new FamilySizePlan{Rows=r.Rows(source)};foreach(var row in p.Rows){row.Create=row.Diameter!=15;row.State=row.Create?"Sẽ tạo; đã căn chữ":"Đã có — giữ nguyên";}return p;},(r,p)=>{writes++;return p.Rows.Count(x=>x.Create);})){f.Show();Check(Find<NumericUpDown>(f,"FamilyPadding").Value==.6M&&!Find<Button>(f,"CreateFamilySizes").Enabled,"Family creation inherits sampled clearance and starts as read-only draft");Find<TextBox>(f,"FamilyDiameters").Text="15,28,35";Find<Button>(f,"InspectFamilySizes").PerformClick();Check(scans==1&&Find<Button>(f,"CreateFamilySizes").Enabled&&Find<DataGridView>(f,"FamilyPreview").Rows.Count==3,"Inspection shows existing diameter separately from new sizes");Capture(f,"ui-add-family-sizes");f.Size=f.MinimumSize;Capture(f,"ui-add-family-sizes-minimum");Find<TextBox>(f,"FamilySuffix").Text="BASE";Check(!Find<Button>(f,"CreateFamilySizes").Enabled,"Changing names invalidates prior review");Find<Button>(f,"InspectFamilySizes").PerformClick();Find<Button>(f,"CreateFamilySizes").PerformClick();Check(writes==1&&f.CreatedCount==2&&!Find<Button>(f,"CreateFamilySizes").Enabled,"Creation executes one reviewed new-only batch");f.Close();}
        using(var f=new LabelManagerForm(new LabelCatalog(),()=>new LabelCatalog(),(s,e)=>false,n=>7,new ScaleContext(),null,false,()=>new ManagerForm(new Profile(),"fixture",p=>"",p=>"",null))){f.Show();var add=Find<Button>(f,"AddFamilySizes");Check(All(f).All(c=>c.Name!="PickSystem")&&add.Parent.Parent==Find<Button>(f,"LabelLibrary").Parent.Parent,"Add sizes and new system share the Create group; redundant in-manager system pick is removed");Capture(f,"ui-create-group");f.Size=f.MinimumSize;Capture(f,"ui-create-group-minimum");add.PerformClick();Check(f.DialogResult==DialogResult.Ignore,"Add sizes returns to the drawing for a concrete sample");}
        var definitions=new List<DrawingLayerInfo>{new DrawingLayerInfo{LayerName="Mr.T_CO2_D28_RAW",LinetypeName="Mr.T_CO2_D28_RAW",Text="D28.CO2",Managed=true,Writable=true,HasFamilyDefaults=true,FamilyScale=.15,FamilyWidth=15,FamilySource="D15.CO2",State="Sẵn sàng"},new DrawingLayerInfo{LayerName="Mr.T_OTHER",Text="Other",Managed=true,Writable=true}};using(var f=new PipePickerForm(definitions,2)){f.Show();var g=Find<DataGridView>(f,"DrawingGrid");g.CurrentCell=g.Rows.Cast<DataGridViewRow>().Single(r=>((DrawingLayerInfo)r.DataBoundItem).HasFamilyDefaults).Cells[0];Check(Find<CheckBox>(f,"UseFamilyDefaults").Checked&&!f.KeepScale&&f.EntityScale==.15&&f.GlobalWidth==15&&f.ColorByLayer&&!Find<CheckBox>(f,"KeepEntityScale").Checked&&Find<CheckBox>(f,"AssignColorByLayer").Checked,"New family targets default to sampled color, scale and constant width during assignment");Capture(f,"ui-assign-family-defaults");f.Size=f.MinimumSize;Capture(f,"ui-assign-family-defaults-minimum");Find<CheckBox>(f,"UseFamilyDefaults").Checked=false;Check(f.KeepScale&&!f.GlobalWidth.HasValue&&!f.ColorByLayer,"Turning off sampled defaults respects ordinary assignment choices");Find<TextBox>(f,"DrawingQuery").Text="none";Check(!Find<CheckBox>(f,"UseFamilyDefaults").Checked&&!Find<Button>(f,"AssignPipe").Enabled,"Empty filter clears stale template selection safely");f.Close();}
        using(var f=new PickModeForm(1)){f.Show();Capture(f,"ui-pick-mode");Find<Button>(f,"PickSelectSimilar").PerformClick();Check(f.Similar&&f.DialogResult==DialogResult.OK,"External picker can request native Select Similar");}using(var f=new PickModeForm(0)){f.Show();Find<Button>(f,"PickBySystem").PerformClick();Check(!f.Similar&&f.DialogResult==DialogResult.OK,"External picker retains label-system mode");}
        log.Add("RESULT: PASS; Core/WinForms only. Native inheritance, glyph measurement, Select Similar and Undo require CAD tests.");return 0;
    }catch(Exception ex){log.Add("FAIL: "+ex);Console.WriteLine(ex);return 1;}finally{File.WriteAllLines(Path.Combine(evidence,"family-tests.txt"),log);}}
}
